+package hotel.messages;
+
+public final class ArchiveCopyRule implements EmailRule {
+    private final boolean testModeEnabled;
+
+    public ArchiveCopyRule(boolean testModeEnabled) {
+        this.testModeEnabled = testModeEnabled;
+    }
+
+    @Override
+    public EmailRuleResult apply(String to, String subject, String body) {
+        if (testModeEnabled) {
+            return new EmailRuleResult(to, subject, body);
+        }
+        String newSubject = "[Cópia] " + subject;
+        return new EmailRuleResult(to, subject, body).withAdditionalMessage(createArchiveMessage(to, newSubject, body));
+    }
+
+    private String createArchiveMessage(String originalTo, String newSubject, String body) {
+        return "EMAIL|arquivo@pousadamarealta.com.br|" + newSubject + "|" + body + "|" + originalTo;
+    }
+}
diff --git a/src/main/java/hotel/messages/EmailProcessor.java b/src/main/java/hotel/messages/EmailProcessor.java
new file mode 100644
index 0000000..cb9ba6a
--- /dev/null
+++ b/src/main/java/hotel/messages/EmailProcessor.java
@@ -0,0 +1,46 @@
+package hotel.messages;
+
+import java.util.ArrayList;
+import java.util.List;
+
+public final class EmailProcessor {
+    private final List<EmailRule> rules;
+
+    public EmailProcessor(List<EmailRule> rules) {
+        this.rules = rules;
+    }
+
+    public ProcessedEmail process(String to, String subject, String body) {
+        List<ProcessedEmail> additionalEmails = new ArrayList<>();
+        String currentTo = to;
+        String currentSubject = subject;
+        String currentBody = body;
+        String status = "SENT";
+
+        for (EmailRule rule : rules) {
+            EmailRuleResult result = rule.apply(currentTo, currentSubject, currentBody);
+            if (result.blocked()) {
+                status = "BLOCKED";
+                currentTo = to;
+                currentSubject = subject;
+                currentBody = body;
+                break;
+            }
+            currentTo = result.to();
+            currentSubject = result.subject();
+            currentBody = result.body();
+            for (String additionalMessage : result.additionalMessages()) {
+                additionalEmails.add(parseAdditionalMessage(additionalMessage));
+            }
+        }
+
+        return new ProcessedEmail(currentTo, currentSubject, currentBody, status, additionalEmails);
+    }
+
+    private static ProcessedEmail parseAdditionalMessage(String message) {
+        String[] parts = message.split("\\|", 5);
+        return new ProcessedEmail(parts[1], parts[2], parts[3], "SENT", List.of());
+    }
+
+    public record ProcessedEmail(String to, String subject, String body, String status, List<ProcessedEmail> additionalEmails) {}
+}
