    49	    private Message storeMessage(String channel, String to, String subject, String body, String status) {
    50	        try (Connection connection = dataSource.getConnection();
    51	                PreparedStatement insert = connection.prepareStatement(
    52	                        "INSERT INTO messages (channel, recipient, subject, body, status) VALUES (?, ?, ?, ?, ?) RETURNING id")) {
