== EmailProcessor
     1	package hotel.messages;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	
     6	public final class EmailProcessor {
     7	    private final List<EmailRule> rules;
     8	
     9	    public EmailProcessor(List<EmailRule> rules) {
    10	        this.rules = rules;
    11	    }
    12	
    13	    public ProcessedEmail process(String to, String subject, String body) {
    14	        List<ProcessedEmail> additionalEmails = new ArrayList<>();
    15	        String currentTo = to;
    16	        String currentSubject = subject;
    17	        String currentBody = body;
    18	        String status = "SENT";
    19	
    20	        for (EmailRule rule : rules) {
    21	            EmailRuleResult result = rule.apply(currentTo, currentSubject, currentBody);
    22	            if (result.blocked()) {
    23	                status = "BLOCKED";
    24	                currentTo = to;
    25	                currentSubject = subject;
    26	                currentBody = body;
    27	                break;
    28	            }
    29	            currentTo = result.to();
    30	            currentSubject = result.subject();
    31	            currentBody = result.body();
    32	            for (String additionalMessage : result.additionalMessages()) {
    33	                additionalEmails.add(parseAdditionalMessage(additionalMessage));
    34	            }
    35	        }
    36	
    37	        return new ProcessedEmail(currentTo, currentSubject, currentBody, status, additionalEmails);
    38	    }
    39	
    40	    private static ProcessedEmail parseAdditionalMessage(String message) {
    41	        String[] parts = message.split("\\|", 5);
    42	        return new ProcessedEmail(parts[1], parts[2], parts[3], "SENT", List.of());
    43	    }
    44	
    45	    public record ProcessedEmail(String to, String subject, String body, String status, List<ProcessedEmail> additionalEmails) {}
    46	}
