     4	    public static boolean isValid(String email) {
     5	        int atIndex = email.indexOf('@');
     6	        if (atIndex <= 0 || atIndex != email.lastIndexOf('@')) {
     7	            return false;
     8	        }
     9	        int dotIndex = email.indexOf('.', atIndex + 1);
    10	        return dotIndex > atIndex + 1 && dotIndex < email.length() - 1;
    11	    }
